sql.where:
sm.start_at >= #{from}
AND sm.start_at < #{to}
AND sm.status IN

    #{st}


    AND sm.sport_id = #{sportId}


    AND f.region_id = #{regionId}



    AND

        (sm.start_at < TIMESTAMP(DATE(sm.start_at)) + INTERVAL (#{h} + 1) HOUR
         AND sm.end_at > TIMESTAMP(DATE(sm.start_at)) + INTERVAL #{h} HOUR)




    AND (sm.start_at > #{cursorStartAt}
         OR (sm.start_at = #{cursorStartAt} AND sm.match_id > #{cursorMatchId}))

mapper.select:
SELECT sm.match_id, sm.title, sm.created_by, sm.sport_id, s.name AS sport_name, f.facility_id, f.name AS facility_name, f.address, r.name AS region_name, sm.start_at, sm.end_at, sm.min_participants, sm.max_participants, sm.fee_per_person, sm.required_skill, sm.status, sm.photo_url
ORDER BY sm.start_at, sm.match_id
LIMIT #{limit}

SELECT mp.participant_id, mp.match_id, mp.user_id, u.nickname, mp.participation_status, mp.match_side, mp.entry_mmr, mp.joined_at FROM match_participant mp JOIN app_user u ON u.user_id = mp.user_id WHERE mp.match_id IN
#{id}
AND mp.participation_status IN
#{st}
ORDER BY mp.match_id, mp.joined_at, mp.participant_id

SELECT mp.participant_id, mp.match_id, mp.user_id, u.nickname, mp.participation_status, mp.match_side, mp.entry_mmr, mp.joined_at, GREATEST(COALESCE(sr.rated_match_count, 0) - (SELECT COUNT(*) FROM sport_rating_history h WHERE h.user_id = mp.user_id AND h.sport_id = sm.sport_id AND h.calculated_at >= mp.joined_at), 0) AS entry_rated_match_count FROM match_participant mp JOIN social_match sm ON sm.match_id = mp.match_id JOIN app_user u ON u.user_id = mp.user_id LEFT JOIN sport_rating sr ON sr.user_id = mp.user_id AND sr.sport_id = sm.sport_id WHERE mp.match_id = #{matchId} AND mp.participation_status IN
#{st}
ORDER BY mp.joined_at, mp.participant_id

SELECT NULL AS participant_id, ma.match_id, ma.applicant_user_id AS user_id, u.nickname, #{participationStatus} AS participation_status, NULL AS match_side, NULL AS entry_mmr, ma.created_at AS joined_at FROM match_application ma JOIN app_user u ON u.user_id = ma.applicant_user_id WHERE ma.match_id IN
#{id}
AND ma.status = #{waitingStatus} ORDER BY ma.match_id, ma.created_at, ma.application_id
